export const STORAGE_KEY = 'opscotch-monitor.connector-config.v1';
const empty = () => ({ version: 1, activeConnector: 'polling', polling: { url: '' }, live: { url: '', token: '', metricNames: '', dimensions: '' } });
export function loadConnectorConfig(storage = window.localStorage) { const fallback = empty(); try { const stored = JSON.parse(storage.getItem(STORAGE_KEY)); if (stored && stored.version === 1) return { ...fallback, ...stored, polling: { ...fallback.polling, ...stored.polling }, live: { ...fallback.live, ...stored.live } }; const legacyUrl = storage.getItem('url'); if (legacyUrl) return { ...fallback, polling: { url: legacyUrl } }; } catch (_) {} return fallback; }
export function saveConnectorConfig(config, storage = window.localStorage) { const normalized = { ...empty(), ...config, polling: { url: (config.polling?.url || '').trim() }, live: { ...empty().live, ...config.live, url: (config.live?.url || '').trim() } }; storage.setItem(STORAGE_KEY, JSON.stringify(normalized)); return normalized; }
export function clearLiveToken(storage = window.localStorage) { const config = loadConnectorConfig(storage); config.live.token = ''; saveConnectorConfig(config, storage); }
